## Code Example

```typescript
type LogLevel = "debug"|"info"|"warn"|"error";

interface LogRecord {
  level: LogLevel;
  message: string;
  timestamp: number;
  context?: any;
}

interface Destination {
  emit(record: LogRecord): Promise<void>;
}

interface DestinationConfig {
  minLevel: LogLevel;
  formatter?: (record: LogRecord) => string;
}

class Logger {
  private destinations = new Map<string, { destination: Destination; config: DestinationConfig }>();

  register(name: string, destination: Destination, config: DestinationConfig): void {
    this.destinations.set(name, { destination, config });
  }

  unregister(name: string): void {
    this.destinations.delete(name);
  }

  async log(level: LogLevel, message: string, context?: any): Promise<void> {
    const record: LogRecord = {
      level,
      message,
      timestamp: Date.now(),
      context
    };

    const promises = Array.from(this.destinations.entries())
      .filter(([_, { config }]) => this.shouldLog(record.level, config.minLevel))
      .map(async ([_, { destination, config }]) => {
        try {
          const formattedRecord = config.formatter ? config.formatter(record) : record;
          await destination.emit(formattedRecord);
        } catch (error) {
          console.error(`Destination failed:`, error);
        }
      });

    await Promise.allSettled(promises);
  }

  private shouldLog(recordLevel: LogLevel, minLevel: LogLevel): boolean {
    const levels: Record<LogLevel, number> = { debug: 0, info: 1, warn: 2, error: 3 };
    return levels[recordLevel] >= levels[minLevel];
  }
}
```

## Why This Is Asked
The question probes ability to design a dynamic, runtime-extensible cross-cutting concerns system using proxies, with per-method interceptor ordering and async support. It tests API design, runtime extensibility, and trade-offs among common approaches.

## Key Concepts
- Proxy-based interception for runtime extensibility
- Interceptor registry and per-method order
- Async support via promises and proper error propagation
- Trade-offs: Proxy vs Decorator vs Interceptor-chain

## Code Example
```javascript
type Context = { target: any; method: string; args: any[] };
interface Interceptor {
  name: string;
  intercept(ctx: Context, next: () => Promise<any>): Promise<any>;
}
class Registry {
  private map = new Map<string, () => Interceptor>();
  register(name: string, factory: () => Interceptor) { this.map.set(name, factory); }
  createChain(names: string[]): Interceptor[] { return names.map(n => this.map.get(n)!).filter(Boolean); }
}
function createProxy<T>(target: T, registry: Registry, perMethod: Map<string, string[]>): T {
  return new Proxy(target as any, {
    get(obj, prop: string) {
      const orig = (obj as any)[prop];
      if (typeof orig !== 'function') return orig;
      return (...args: any[]) => {
        const order = perMethod.get(prop) || [];
        const chain = registry.createChain(order);
        let idx = -1;
        const next = (): Promise<any> => {
          idx++;
          if (idx >= chain.length) return Promise.resolve(orig.apply(obj, args));
          const interceptor = chain[idx];
          return interceptor.intercept({ target: obj, method: prop, args }, next);
        };
        return next();
      };
    }
  });
}
```

